    "image": "https://cdn.sanity.io/images/xzcgo5ky/production/d0cd39b2a48c815e2be5ef29cc8e3d531934a8a4-1080x1339.jpg?w=600&h=600&fit=fill&crop=entropy&auto=format&sharp=20",
    "imageDetail": "https://cdn.sanity.io/images/xzcgo5ky/production/d0cd39b2a48c815e2be5ef29cc8e3d531934a8a4-1080x1339.jpg?w=1200&h=1200&fit=fill&crop=entropy&auto=format&sharp=30"
