    "image": "https://cdn.sanity.io/images/xzcgo5ky/production/9f285276e31026247407e75645c9795f78fa667c-2364x1792.png?w=600&h=600&fit=fill&crop=entropy&auto=format&sharp=20",
    "imageDetail": "https://cdn.sanity.io/images/xzcgo5ky/production/9f285276e31026247407e75645c9795f78fa667c-2364x1792.png?w=1200&h=1200&fit=fill&crop=entropy&auto=format&sharp=30"
